#include <vector>
#include <numeric>

using namespace std;

class Solution {
public:
    int minimizedMaximum(int n, vector<int>& quantities) {
        int lo = 1, hi = *max_element(quantities.begin(), quantities.end());
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            int cnt = 0;
            for (int q : quantities)
                cnt += (q + mid - 1) / mid;
            if (cnt <= n) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};
